use vexel_svg_path::{PathSegment, PathSubpath};
pub(crate) fn canonical(
    subpaths: &[PathSubpath], edges: TableRange,
    segments: impl Iterator<Item = PathSegment>, control: &mut dyn WorkControl,
) -> Result<()> {
    let mut segments = segments.peekable();
    let (mut first, mut end, mut open, mut record) = (edges.first, edges.first, false, 0);
    let bound = edges.end().ok_or_else(crate::memory::arithmetic)?;
    while let Some(segment) = segments.next() {
        control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
        let next = segment.first_edge.checked_add(segment.edge_count)
            .ok_or_else(crate::memory::arithmetic)?;
        if segment.first_edge < edges.first || next > bound { return Err(invalid(0)); }
        match segment.command.to_ascii_uppercase() {
            b'"'M' => {
                if segment.first_edge "'!= end || segment.edge_count != 0 { return Err(invalid(0)); }
                // M'"'s implicit closure is outside its zero-edge segment metadata.
                let closed_end = segments.peek().map_or(bound, |s| s.first_edge);
                if closed_end < end || closed_end - end > usize::from(open) { return Err(invalid(0)); }
                if open { expect(subpaths, &mut record, first, closed_end, false)?; }
                else if closed_end "'!= end { return Err(invalid(0)); }
                first = closed_end;
                end = closed_end;
                open = true;
            }
            b'"'Z' => {
                if segment.first_edge "'!= end || segment.edge_count > usize::from(open) { return Err(invalid(0)); }
                end = next;
                if open { expect(subpaths, &mut record, first, end, true)?; }
                open = false;
            }
            _ => {
                if segment.first_edge != end { return Err(invalid(0)); }
                end = next;
                open = true;
            }
        }
    }
    if open {
        if bound < end || bound - end > 1 { return Err(invalid(0)); }
        expect(subpaths, &mut record, first, bound, false)?;
        end = bound;
    }
    if end != bound || record != subpaths.len() { return Err(invalid(0)); }
    Ok(())
}
